ask(1720,'joint-signals','Revolute angular velocity dθ/dt and later RPM feature','A supplied joint rotates throughπ/2rad in0.1s without angle wrapping. What average speed in RPM would represent this motion?', [('150RPM','A quarter turn in0.1s is2.5turns/s, or150turns/min.'),('15.71RPM','This computes radians per second but labels that number RPM.'),('300RPM','This usesπ radians per turn rather than2π.')],kind='numerical',ck='table',cites=[(1723,'statement','Velocity(RPM) feature')],ass=['Average speed over the supplied interval; same positive direction; no modulo ambiguity or gear ratio.'],steps=['Divideπ/2 by0.1 to get5πrad/s.','Convert radians to turns using2πrad/turn.','Multiply turns/s by60s/min.'],formulas=[fm('ω_avg=Δθ/Δt; n_RPM=ω_avg·60/(2π)',{'ω_avg':'Average angular speed','Δθ':'Angle change','Δt':'Elapsed time','n_RPM':'Average rotational speed','π':'Circle constant'},{'ω_avg':'rad/s','Δθ':'rad','Δt':'s','n_RPM':'revolutions/min','π':'dimensionless'},['No angle wrapping; same shaft and direction; one revolution equals2πradians.'])])
ask(1730,'fault-evaluation','classification_report precision,recall and F1 fields','For supplied precision0.8 and recall0.5, what is the F1 score?', [('8/13≈0.6154','F1 is2×0.8×0.5/(0.8+0.5).'),('0.65','That is the arithmetic mean rather than the harmonic mean.'),('0.40','That multiplies precision by recall without the harmonic normalization.')],kind='numerical',ck='code',ass=['Positive precision and recall; unweighted binary positive-class F1.'],steps=['Multiply2×0.8×0.5.','Divide by0.8+0.5.'],formulas=[fm('F1=2PR/(P+R)',{'F1':'Harmonic mean of precision and recall','P':'Precision','R':'Recall'},{'F1,P,R':'dimensionless'},['P+R>0; same selected class and evaluation set.'])],primary=[ref('Classification report','https://scikit-learn.org/1.8/modules/generated/sklearn.metrics.classification_report.html','scikit-learn1.8.0','Report fields precision, recall, F1 and support.')])
