ask(1733,'mlp-learning','Combined forward,loss,backpropagation and update phases','For a supplied toy network h=ReLU(wx),ŷ=h,target0 and L=0.5ŷ², let x=2,w=0.5 and eta=0.1. Update only w by one plain gradient step. What are new w and the recomputed loss?', [('0.3 and0.18','Initial h=1 and dL/dw=1×2=2; w_new=0.3, thenŷ_new=0.6 and loss0.18.'),('0.7 and0.98','This adds the gradient step, increasing the weight and loss.'),('0.4 and0.32','This omits the input factor2 from the chain-rule gradient.')],kind='synthesis',difficulty='medium',ass=['All toy values are normalized and dimensionless; positive preactivation before and after update; no bias/regularization; plain gradient descent, not the source model’s Adam optimizer.'],steps=['Forward:wx=1, so h=ŷ=1.','Loss before update is0.5.','Backpropagate dL/dw=ŷ·1·x=2.','Update w=0.5−0.1×2=0.3.','Recomputeŷ=0.6 and L=0.5×0.6²=0.18.'],formulas=[fm('ŷ=max(0,wx); L=0.5ŷ²; g_w=ŷ·1_(wx>0)·x; w_new=w−ηg_w',{'ŷ':'Predicted scalar','x':'Input scalar','w':'Weight before update','w_new':'Weight after update','L':'Half-squared loss for zero target','g_w':'Loss derivative with respect to w','η':'Positive learning rate','1_(wx>0)':'ReLU derivative for nonzero preactivation'},{'ŷ,x,w,w_new,L,g_w,η,1_(wx>0)':'dimensionless'},['Zero target; no bias or regularization; positive/nonzero preactivation in this example; only w updated.'])])
